public class CollectionModificationExample {
    public static void main(String[] args) {
        var orders = new ArrayList<>(List.of("Order1", "Order2", "Order3", "Order4"));

        // WRONG: modification during for-each iteration
        // for (var order : orders) {
        //     if (order.startsWith("Order2")) {
        //         orders.remove(order); // ConcurrentModificationException!
        //     }
        // }

        // Solution 1: removeIf (best for simple conditions)
        orders.removeIf(order -> order.startsWith("Order2"));

        // Solution 2: Iterator.remove() for complex logic
        var iterator = orders.iterator();
        while (iterator.hasNext()) {
            var order = iterator.next();
            if (order.equals("Order3")) {
                iterator.remove(); // safe removal through iterator
            }
        }

        // Solution 3: collect changes, apply after iteration
        var toRemove = orders.stream()
            .filter(order -> order.startsWith("Order"))
            .toList();
        orders.removeAll(toRemove);
    }
}

// Unchecked exception for business logic errors
public class OrderNotFoundException extends RuntimeException {
    public OrderNotFoundException(String message) {
        super(message); // pass message to RuntimeException
    }

    public OrderNotFoundException(String message, Throwable cause) {
        super(message, cause); // chain exceptions
    }
}

// Usage in service layer
@Service
public class OrderService {
    public Order findOrder(Long orderId) {
        return repository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(
                "Order not found with ID: " + orderId));
    }
}

// Handling in REST controller
@RestControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(OrderNotFoundException.class)
    public ResponseEntity<String> handleOrderNotFound(OrderNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(ex.getMessage());
    }
}
